import CoreImage
import CoreImage.CIFilterBuiltins
import ImageIO
import Photos
import UIKit

enum Look: String, CaseIterable, Identifiable {
    case natural, kiln, fjord, cinder, salt, graphite

    var id: String { rawValue }
    var title: String { rawValue.capitalized }

    private static let cubeSize = 33

    /// Colour cubes generated by tools/make_looks.py: 16-bit RGB, red changing fastest.
    private static let cubes: [Look: Data] = {
        var result: [Look: Data] = [:]
        for look in allCases where look != .natural {
            guard let url = Bundle.main.url(forResource: look.rawValue, withExtension: "lut"),
                  let encoded = try? Data(contentsOf: url),
                  encoded.count == cubeSize * cubeSize * cubeSize * 6 else { continue }
            var floats = [Float](repeating: 1, count: cubeSize * cubeSize * cubeSize * 4)
            encoded.withUnsafeBytes { bytes in
                for entry in 0..<(encoded.count / 6) {
                    for channel in 0..<3 {
                        let value = bytes.loadUnaligned(fromByteOffset: (entry * 3 + channel) * 2, as: UInt16.self)
                        floats[entry * 4 + channel] = Float(UInt16(littleEndian: value)) / 65535
                    }
                }
            }
            result[look] = floats.withUnsafeBufferPointer { Data(buffer: $0) }
        }
        return result
    }()

    func apply(to image: CIImage) -> CIImage {
        guard let cube = Self.cubes[self], let colorSpace = CGColorSpace(name: CGColorSpace.sRGB) else {
            return image
        }
        let filter = CIFilter.colorCubeWithColorSpace()
        filter.inputImage = image
        filter.cubeDimension = Float(Self.cubeSize)
        filter.cubeData = cube
        filter.colorSpace = colorSpace
        return filter.outputImage ?? image
    }
}

enum PhotoFrame: String {
    case none, border, mat

    var title: String {
        switch self {
        case .none: return "No Frame"
        case .border: return "Border"
        case .mat: return "Mat"
        }
    }

    var next: PhotoFrame {
        switch self {
        case .none: return .border
        case .border: return .mat
        case .mat: return .none
        }
    }

    private var color: CIColor {
        CIColor(red: 0.96, green: 0.95, blue: 0.92)
    }

    /// Margins as fractions of the photo's short edge: sides, top, bottom.
    private var margins: (side: CGFloat, top: CGFloat, bottom: CGFloat) {
        switch self {
        case .none: return (0, 0, 0)
        case .border: return (0.025, 0.025, 0.025)
        case .mat: return (0.06, 0.06, 0.18)
        }
    }

    func apply(to image: CIImage) -> CIImage {
        guard self != .none else { return image }
        let short = min(image.extent.width, image.extent.height)
        let side = (margins.side * short).rounded()
        let top = (margins.top * short).rounded()
        let bottom = (margins.bottom * short).rounded()
        let canvas = CGRect(
            x: 0,
            y: 0,
            width: image.extent.width + 2 * side,
            height: image.extent.height + top + bottom
        )
        let moved = image.transformed(by: CGAffineTransform(
            translationX: side - image.extent.minX,
            y: bottom - image.extent.minY
        ))
        return moved.composited(over: CIImage(color: color).cropped(to: canvas))
    }
}

enum GrainLevel: String {
    case off, fine, heavy

    var title: String {
        switch self {
        case .off: return "No Grain"
        case .fine: return "Fine Grain"
        case .heavy: return "Heavy Grain"
        }
    }

    var next: GrainLevel {
        switch self {
        case .off: return .fine
        case .fine: return .heavy
        case .heavy: return .off
        }
    }

    var amount: Double {
        switch self {
        case .off: return 0
        case .fine: return 0.3
        case .heavy: return 0.7
        }
    }
}

struct DevelopSettings: Equatable {
    var look: Look = .natural
    var grain: GrainLevel = .off
    var frame: PhotoFrame = .none
}

enum DevelopError: LocalizedError {
    case unreadable
    case exportFailed
    case photosDenied
    case saveFailed

    var errorDescription: String? {
        switch self {
        case .unreadable: return "This photo couldn't be opened."
        case .exportFailed: return "The photo couldn't be finished. Try again."
        case .photosDenied: return "Photos access is off. Turn it on in Settings to save."
        case .saveFailed: return "The photo couldn't be saved. Try again."
        }
    }
}

/// Turns a captured photo into the finished image: crop, look, grain, frame.
final class PhotoDeveloper {
    /// Display P3 throughout, so the preview shows the same colour as the saved file.
    private static let context = CIContext(
        options: CGColorSpace(name: CGColorSpace.displayP3).map { [.outputColorSpace: $0] } ?? [:]
    )

    private let source: CIImage
    private let preview: CIImage
    private let thumbnail: CIImage

    private static let previewLongEdge = 1500
    private static let thumbnailLongEdge: CGFloat = 220
    /// Grain cells keep the same size relative to the photo, so the preview matches the saved file.
    private static let grainReferenceEdge: CGFloat = 1600

    /// A fast stand-in made from the viewfinder frame while the real photo is processed.
    static func quickPreview(of placeholder: UIImage, settings: DevelopSettings, ratio: CaptureRatio) -> UIImage? {
        guard let cgImage = placeholder.cgImage else { return nil }
        var fast = settings
        fast.grain = .off
        let output = develop(crop(CIImage(cgImage: cgImage), to: ratio), fast)
        guard let rendered = context.createCGImage(output, from: output.extent) else { return nil }
        return UIImage(cgImage: rendered)
    }

    init(data: Data, ratio: CaptureRatio) throws {
        // The full photo stays undecoded until saving. The preview comes from one fast downsample.
        guard let decoded = CIImage(data: data, options: [.applyOrientationProperty: true]),
              let small = Self.downsampled(data, longEdge: Self.previewLongEdge) else {
            throw DevelopError.unreadable
        }
        source = Self.crop(decoded, to: ratio).settingProperties(Self.uprightProperties(decoded.properties))

        guard let previewImage = Self.flattened(Self.crop(CIImage(cgImage: small), to: ratio)) else {
            throw DevelopError.unreadable
        }
        preview = previewImage

        let thumbnailScale = min(1, Self.thumbnailLongEdge / max(previewImage.extent.width, previewImage.extent.height))
        guard let thumbnailImage = Self.flattened(previewImage.applyingFilter("CILanczosScaleTransform", parameters: [
            kCIInputScaleKey: thumbnailScale,
            kCIInputAspectRatioKey: 1
        ])) else {
            throw DevelopError.unreadable
        }
        thumbnail = thumbnailImage
    }

    func renderPreview(_ settings: DevelopSettings) -> UIImage? {
        image(from: Self.develop(preview, settings))
    }

    func renderThumbnails() -> [Look: UIImage] {
        var result: [Look: UIImage] = [:]
        for look in Look.allCases {
            result[look] = image(from: look.apply(to: thumbnail))
        }
        return result
    }

    private func image(from output: CIImage) -> UIImage? {
        guard let rendered = Self.context.createCGImage(output, from: output.extent) else { return nil }
        return UIImage(cgImage: rendered)
    }

    #if DEBUG
    /// Renders at full size, so tests can compare the saved photo with the preview.
    func renderFullSize(_ settings: DevelopSettings) -> UIImage? {
        image(from: Self.develop(source, settings))
    }
    #endif

    /// Writes the finished photo to the library.
    func save(_ settings: DevelopSettings) async throws {
        guard let colorSpace = CGColorSpace(name: CGColorSpace.displayP3) else {
            throw DevelopError.exportFailed
        }
        let developed = Self.develop(source, settings).settingProperties(source.properties)
        let options = [CIImageRepresentationOption(rawValue: kCGImageDestinationLossyCompressionQuality as String): 0.95]
        guard let jpeg = Self.context.jpegRepresentation(of: developed, colorSpace: colorSpace, options: options) else {
            throw DevelopError.exportFailed
        }

        let access = await PHPhotoLibrary.requestAuthorization(for: .addOnly)
        guard access == .authorized || access == .limited else {
            throw DevelopError.photosDenied
        }
        do {
            try await PHPhotoLibrary.shared().performChanges {
                PHAssetCreationRequest.forAsset().addResource(with: .photo, data: jpeg, options: nil)
            }
        } catch {
            throw DevelopError.saveFailed
        }
    }

    private static func develop(_ image: CIImage, _ settings: DevelopSettings) -> CIImage {
        let toned = settings.look.apply(to: image)
        let grained = addGrain(to: toned, amount: settings.grain.amount)
        return settings.frame.apply(to: grained)
    }

    private static func addGrain(to image: CIImage, amount: Double) -> CIImage {
        guard amount > 0, let noise = CIFilter.randomGenerator().outputImage else { return image }
        let longEdge = max(image.extent.width, image.extent.height)
        let cell = max(1, longEdge / grainReferenceEdge)
        // Upscaling softens the noise, so the unscaled preview needs less to match the saved photo.
        let strength = CGFloat(amount) * (cell > 1 ? 0.68 : 0.53)
        let area = image.extent
            .applying(CGAffineTransform(scaleX: 1 / cell, y: 1 / cell))
            .insetBy(dx: -8, dy: -8)
            .integral

        // The generator's alpha is random too, which would darken everything if left in place.
        let grain = noise
            .cropped(to: area)
            .settingAlphaOne(in: area)
            .applyingFilter("CIColorControls", parameters: [kCIInputSaturationKey: 0])
            .transformed(by: CGAffineTransform(scaleX: cell, y: cell))
            .applyingGaussianBlur(sigma: 0.45 * cell)
            .applyingFilter("CIColorMatrix", parameters: [
                "inputRVector": CIVector(x: strength, y: 0, z: 0, w: 0),
                "inputGVector": CIVector(x: 0, y: strength, z: 0, w: 0),
                "inputBVector": CIVector(x: 0, y: 0, z: strength, w: 0),
                "inputAVector": CIVector(x: 0, y: 0, z: 0, w: 0),
                "inputBiasVector": CIVector(x: 0.5 - strength / 2, y: 0.5 - strength / 2, z: 0.5 - strength / 2, w: 1)
            ])
            .cropped(to: image.extent)

        // A flat 0.5, which leaves the photo unchanged in a linear light blend.
        let neutral = grain.applyingFilter("CIColorMatrix", parameters: [
            "inputRVector": CIVector(x: 0, y: 0, z: 0, w: 0),
            "inputGVector": CIVector(x: 0, y: 0, z: 0, w: 0),
            "inputBVector": CIVector(x: 0, y: 0, z: 0, w: 0),
            "inputAVector": CIVector(x: 0, y: 0, z: 0, w: 0),
            "inputBiasVector": CIVector(x: 0.5, y: 0.5, z: 0.5, w: 1)
        ])
        .cropped(to: image.extent)

        // Follows the photo's brightness: none at black, most in the midtones, some in highlights.
        let luma = CIVector(x: 0.2126, y: 0.7152, z: 0.0722, w: 0)
        let mask = image
            .applyingFilter("CIColorMatrix", parameters: ["inputRVector": luma, "inputGVector": luma, "inputBVector": luma])
            .applyingFilter("CIToneCurve", parameters: [
                "inputPoint0": CIVector(x: 0, y: 0),
                "inputPoint1": CIVector(x: 0.25, y: 0.42),
                "inputPoint2": CIVector(x: 0.5, y: 0.68),
                "inputPoint3": CIVector(x: 0.75, y: 0.70),
                "inputPoint4": CIVector(x: 1, y: 0.50)
            ])

        return grain
            .applyingFilter("CIBlendWithMask", parameters: [kCIInputBackgroundImageKey: neutral, kCIInputMaskImageKey: mask])
            .applyingFilter("CILinearLightBlendMode", parameters: [kCIInputBackgroundImageKey: image])
            .cropped(to: image.extent)
    }

    /// Centre-crops to the ratio, turning it sideways if the phone was held sideways.
    private static func crop(_ image: CIImage, to ratio: CaptureRatio) -> CIImage {
        let extent = image.extent
        let target = extent.width > extent.height ? 1 / ratio.widthOverHeight : ratio.widthOverHeight
        var width = extent.width
        var height = extent.height
        if width / height > target {
            width = (height * target).rounded()
        } else {
            height = (width / target).rounded()
        }
        let rect = CGRect(
            x: extent.minX + ((extent.width - width) / 2).rounded(),
            y: extent.minY + ((extent.height - height) / 2).rounded(),
            width: width,
            height: height
        )
        return image.cropped(to: rect)
            .transformed(by: CGAffineTransform(translationX: -rect.minX, y: -rect.minY))
    }

    /// Decodes a small upright copy of the photo without touching its full resolution.
    private static func downsampled(_ data: Data, longEdge: Int) -> CGImage? {
        let sourceOptions = [kCGImageSourceShouldCache: false] as CFDictionary
        guard let source = CGImageSourceCreateWithData(data as CFData, sourceOptions) else { return nil }
        let options = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: longEdge,
            kCGImageSourceShouldCacheImmediately: true
        ] as CFDictionary
        return CGImageSourceCreateThumbnailAtIndex(source, 0, options)
    }

    /// Bakes the work done so far into pixels, so each later render starts from here.
    private static func flattened(_ image: CIImage) -> CIImage? {
        guard let rendered = context.createCGImage(image, from: image.extent.integral) else { return nil }
        return CIImage(cgImage: rendered)
    }

    /// The pixels are already upright, so the saved file must not ask viewers to rotate them again.
    private static func uprightProperties(_ properties: [String: Any]) -> [String: Any] {
        var upright = properties
        upright[kCGImagePropertyOrientation as String] = 1
        if var tiff = upright[kCGImagePropertyTIFFDictionary as String] as? [String: Any] {
            tiff[kCGImagePropertyTIFFOrientation as String] = 1
            upright[kCGImagePropertyTIFFDictionary as String] = tiff
        }
        return upright
    }
}
